def median(l: list):
    if not l:
        raise ValueError("The list must not be empty.")
    l.sort()
    n = len(l)
    if n % 2 == 1:
        return l[n // 2]
    else:
        return (l[n // 2 - 1] + l[n // 2]) / 2.0

